```ts
export interface StickerRecord {
  id: number;
  imageBase64: string;
  tags: readonly string[];
}

export type GalleryView =
  | { kind: "invalid"; items: [] }
  | { kind: "error"; message: string; items: [] }
  | { kind: "empty"; items: [] }
  | { kind: "ready"; items: StickerRecord[] };

export function buildStickerGallery(
  query: string,
  records: readonly StickerRecord[],
  error: string | null = null,
): GalleryView {
  const needle = query.trim();
  if (needle.length < 2) return { kind: "invalid", items: [] };
  if (error !== null) return { kind: "error", message: error, items: [] };

  const matches = records.filter(record =>
    Number.isInteger(record.id) &&
    typeof record.imageBase64 === "string" && record.imageBase64.length > 0 &&
    Array.isArray(record.tags) && record.tags.every(tag => typeof tag === "string") &&
    record.tags.some(tag => tag.includes(needle)),
  );
  if (matches.length === 0) return { kind: "empty", items: [] };
  return {
    kind: "ready",
    items: matches.map(record => ({ ...record, tags: [...record.tags] })),
  };
}
```

