import { StickerRecord, buildStickerGallery } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function jsonEqual(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), message);
}

const records: readonly StickerRecord[] = [
  { id: 1, imageBase64: 'one', tags: ['Red Panda', 'Animal'] },
  { id: 2, imageBase64: 'two', tags: ['pAnDa bear', 'Second'] },
  { id: 3, imageBase64: 'three', tags: ['Other'] },
];
jsonEqual(buildStickerGallery('  PANda ', records), {
  kind: 'ready',
  items: [
    { id: 1, imageBase64: 'one', tags: ['Red Panda', 'Animal'] },
    { id: 2, imageBase64: 'two', tags: ['pAnDa bear', 'Second'] },
  ],
}, 'matching is trimmed, case-insensitive, and ordered');

jsonEqual(buildStickerGallery(' x ', records, 'failure'), { kind: 'invalid', items: [] }, 'short query takes priority over error');
jsonEqual(buildStickerGallery('xy', records, 'failure'), { kind: 'error', message: 'failure', items: [] }, 'error returned for valid query');
jsonEqual(buildStickerGallery('zz', records), { kind: 'empty', items: [] }, 'no matches returns empty');
jsonEqual(buildStickerGallery('😀', [{ id: 9, imageBase64: 'x', tags: ['😀'] }]), { kind: 'ready', items: [{ id: 9, imageBase64: 'x', tags: ['😀'] }] }, 'query length uses Unicode code units');

const malformed = [
  { id: 1.5, imageBase64: 'bad', tags: ['match'] },
  { id: 2, imageBase64: '', tags: ['match'] },
  { id: 3, imageBase64: 'bad', tags: 'match' },
  { id: 4, imageBase64: 'bad', tags: ['match', 7] },
  { id: 5, imageBase64: 'good', tags: ['MATCH', 'last'] },
] as unknown as readonly StickerRecord[];
jsonEqual(buildStickerGallery('match', malformed), {
  kind: 'ready',
  items: [{ id: 5, imageBase64: 'good', tags: ['MATCH', 'last'] }],
}, 'malformed records are ignored');

const mutableTags = ['Copy Match', 'tail'];
const mutableRecords: StickerRecord[] = [{ id: 10, imageBase64: 'image', tags: mutableTags }];
const snapshot = JSON.stringify(mutableRecords);
const result = buildStickerGallery('match', mutableRecords);
assert(JSON.stringify(mutableRecords) === snapshot, 'inputs are not mutated');
assert(result.kind === 'ready', 'copy test produces ready result');
if (result.kind === 'ready') {
  assert(result.items[0] !== mutableRecords[0], 'returned record is copied');
  assert(result.items[0].tags !== mutableRecords[0].tags, 'returned tags are copied');
  (result.items[0].tags as string[])[0] = 'changed';
  assert(mutableTags[0] === 'Copy Match', 'returned tag mutation does not affect input');
}

const tagOrder = buildStickerGallery('a', records);
jsonEqual(tagOrder, { kind: 'invalid', items: [] }, 'one-code-unit query is invalid');

